fn is_sorted(arr: &Vec<i32>) -> bool {
    // Check if the array is sorted in non-decreasing order
    // We only need to check consecutive elements since:
    // If for all i, arr[i] <= arr[i+1], then for any i < j, arr[i] <= arr[j]
    for i in 0..arr.len() - 1 {
        if arr[i] > arr[i + 1] {
            return false;
        }
    }
    true
}